@'
import fs from 'node:fs';
import path from 'node:path';
const root=path.resolve('skills/load-balancing-and-routing');
const files=['SKILL.md','references/connection-lifetime-and-l4.md','references/routing-modes.md'];
const checks=[];
for(const file of files){
  const text=fs.readFileSync(path.join(root,file),'utf8');
  for(const match of text.matchAll(/\[[^\]]*\]\(([^)\s]+)(?:\s+[^)]*)?\)/g)){
    const target=match[1];
    if(/^(?:https?:|mailto:)/.test(target))continue;
    const [resource,anchor]=target.split('#');
    const resolved=path.resolve(root,path.dirname(file),decodeURIComponent(resource));
    const exists=fs.existsSync(resolved);
    let anchorFound=true;
    if(anchor&&exists){const content=fs.readFileSync(resolved,'utf8'); const anchors=[...content.matchAll(/^#{1,6}\s+(.+)$/gm)].map(m=>m[1].toLowerCase().replace(/[`*_]/g,'').replace(/[^\p{L}\p{N}\s-]/gu,'').replace(/\s/g,'-')); anchorFound=anchors.includes(decodeURIComponent(anchor));}
    checks.push({file,target,exists,anchorFound});
  }
}
console.log(JSON.stringify({checked:checks.length,checks},null,2));
if(checks.some(c=>!c.exists||!c.anchorFound))process.exitCode=1;
